from author import *
b=[]
def add(a,n,ops):b.append(act(a,n,ops))
def new(kind,**props):return dict(new=kind,props=props)
def view(angle=45,orbit=False):return dict(op='view3d',angle=angle,orbit=orbit)
def proc(node,k,v):return setp(k,v,node,resource_property='process_material',restart=True,filter=k.replace('_',' '))
def surf(node,k,v):return setp(k,v,node,resource_property='draw_pass_1',resource_chain=['material'],filter=k.replace('_',' '))
def group(name):return [dict(op='add',class_name='Node3D',name=name),at(.3,**setp('script',{'resource':'res://effect.gd'},name))]
def surface(texture='soft-dot.tres',blend=0):return new('StandardMaterial3D',shading_mode=0,transparency=1,vertex_color_use_as_albedo=True,billboard_mode=3,billboard_keep_scale=True,blend_mode=blend,albedo_texture={'resource':'res://assets/'+texture})
def mesh(size=.8,texture='soft-dot.tres',blend=0):return new('QuadMesh',size={'v2':[size,size]},material=surface(texture,blend))
def sphere(radius=.035):return new('SphereMesh',radius=radius,height=radius*2,radial_segments=8,rings=4,material=new('StandardMaterial3D',shading_mode=0,transparency=1,vertex_color_use_as_albedo=True))
def process(speed=(1,2),gravity=(0,0,0),spread=45,ramp='hot-fade.tres',**kw):return new('ParticleProcessMaterial',**(dict(direction={'v3':[0,1,0]},initial_velocity_min=speed[0],initial_velocity_max=speed[1],gravity={'v3':list(gravity)},spread=spread,color_ramp={'resource':'res://assets/'+ramp})|kw))
def layer(parent,name,amount,life,draw,behavior,one=True,**extra):
 return dict(op='add',node=parent,class_name='GPUParticles3D',name=name,properties=dict(amount=amount,lifetime=life,one_shot=one,explosiveness=1 if one else 0,emitting=False,process_material=behavior,draw_pass_1=draw,use_fixed_seed=True,seed=7270,visibility_aabb={'aabb':[-8,-3,-8,16,14,16]},**extra))
def solo(parent,name):return setp('solo_layer',name,parent)
def play(parent):return dict(op='call',node=parent,method='play')
def switch(old,new,heading):return [setp('visible',False,old),at(.3,**setp('heading',heading)),*[{**x,'at':.6+i*.35} for i,x in enumerate(group(new))]]
A='Build An Explosion'
add(A,'Start with the empty three-dimensional stage, using Forward Plus on Metal for the later contact-driven sub-emitter. We will build an explosion from separate visual jobs: a flash, a hot expansion, sparks, a smoke tail, and a ring. The editor preview repeats each event so we can inspect its complete life.',[dict(op='open',path='res://arena.tscn'),at(.5,**view()),*[{**x,'at':1+i*.35} for i,x in enumerate(group('Explosion'))]])
add(A,'Add one short-lived flash particle with a large soft quad. Its additive material makes a bright onset. This layer lasts less than a fifth of a second; it should announce the event without pretending to describe the whole explosion.',[layer('Explosion','Flash',1,.18,mesh(2,blend=1),process((0,0),spread=0,ramp='flash-fade.tres')),at(.4,**solo('Explosion','Flash')),at(.8,**play('Explosion'))])
add(A,'Add the hot expansion. Twelve small quads move outward while a growth curve enlarges them. Solo this layer. Its short, changing silhouette carries the peak; the flash only made that peak easier to notice.',[layer('Explosion','Hot',12,.7,mesh(.7,blend=1),process((1,2),spread=180,scale_min=.7,scale_max=1.4,scale_curve={'resource':'res://assets/grow.tres'})),at(.5,**solo('Explosion','Hot')),at(.9,**play('Explosion'))])
add(A,'Add mesh sparks with faster launch and downward gravity. These particles give the eye a direction to follow after the flash. A few readable trajectories are more useful here than a dense cloud of identical points.',[layer('Explosion','Sparks',32,1.2,sphere(),process((4,7),(0,-6,0),90)),at(.5,**solo('Explosion','Sparks')),at(.9,**play('Explosion'))])
add(A,'Build the slower smoke tail with alpha-blended quads. It rises, expands, and fades over more than two seconds. Soloing it makes its timing clear: smoke explains the aftermath, not the impact itself.',[layer('Explosion','Smoke',18,2.4,mesh(1),process((.5,1),spread=20,ramp='smoke-fade.tres',scale_min=1,scale_max=2,scale_curve={'resource':'res://assets/grow.tres'})),at(.5,**solo('Explosion','Smoke')),at(.9,**play('Explosion'))])
add(A,'Add an expanding ring, then show every layer together. The ring is another soft textured particle, with a different silhouette. Its scale curve creates expansion; its lifetime and alpha ramp end the image.',[layer('Explosion','Ring',1,.65,mesh(1,'ring.tres',1),process((0,0),spread=0,ramp='flash-fade.tres',scale_min=4,scale_max=4,scale_curve={'resource':'res://assets/grow.tres'})),at(.5,**solo('Explosion','Ring')),at(4,**solo('Explosion','')),at(4.4,**play('Explosion'))])
add(A,'Remove the smoke tail for one comparison, then restore it. Next reduce the spark count from thirty-two to sixteen. Keep the version whose onset, peak, and decay still read. More particles are a cost, not an explanation.',[setp('smoke_enabled',False,'Explosion'),at(.3,**play('Explosion')),at(4,**setp('smoke_enabled',True,'Explosion')),at(4.4,**setp('amount',16,'Explosion/Sparks')),at(4.8,**play('Explosion')),at(10,op='save_branch',node='Explosion',path='res://effects/explosion.tscn'),at(10.5,op='save')])
A='Build Smoke And Fire'
add(A,'Start a campfire scene with a continuous smoke plume. Continuous means new particles are born throughout the cycle. The plume has a slow upward motion and a broadening alpha silhouette, so it reads as smoke before we add a flame.',switch('Explosion','Campfire',A)+[at(1.5,**layer('Campfire','Smoke',40,3,mesh(.8),process((.5,.9),spread=12,ramp='smoke-fade.tres',scale_min=1,scale_max=2,scale_curve={'resource':'res://assets/grow.tres'}),False)),at(2,**setp('preview_interval',6.5,'Campfire'))])
add(A,'Add a faster, shorter flame layer, then a few small embers. The alpha smoke darkens and softens the scene; additive flame adds light to the image. Those different visual jobs justify different material choices.',[layer('Campfire','Flame',32,.8,mesh(.5,blend=1),process((1,2),spread=12),False),at(.5,**layer('Campfire','Embers',16,1.5,sphere(.025),process((1,3),(0,-1.5,0),25),False)),at(1,**play('Campfire'))])
add(A,'Change the environment from dark to light, then restore it. Inspect both flame and smoke against each background. Additive blending can disappear into a bright scene, while alpha smoke depends on contrast and overlap.',[setp('background_color',{'color':'dbe2df'},'WorldEnvironment',resource_property='environment'),at(5,**setp('background_color',{'color':'09101a'},'WorldEnvironment',resource_property='environment'))])
add(A,'Here is an intentionally crowded plume. Increase the smoke count and size, then reduce both. Overlapping transparent cards add drawing work and may introduce ordering artifacts. Keep the shape, but remove layers that do not improve its message.',[setp('amount',240,'Campfire/Smoke'),at(.3,**proc('Campfire/Smoke','scale_max',4)),at(5,**setp('amount',40,'Campfire/Smoke')),at(5.3,**proc('Campfire/Smoke','scale_max',2))])
add(A,'Assign this original four-cell smoke texture. The grid is visible in the actual material preview. Set four horizontal frames, one vertical frame, and a single animation cycle. The process animation speed advances through that grid over each particle’s life.',[surf('Campfire/Smoke','albedo_texture',{'resource':'res://assets/smoke-flipbook.png'}),at(.4,op='resource',node='Campfire/Smoke',property='draw_pass_1',resource_chain=['material','albedo_texture']),at(4,**surf('Campfire/Smoke','particles_anim_h_frames',4)),at(4.3,**surf('Campfire/Smoke','particles_anim_v_frames',1)),at(4.6,**surf('Campfire/Smoke','particles_anim_loop',False)),at(5,**proc('Campfire/Smoke','anim_speed_min',1)),at(5.3,**proc('Campfire/Smoke','anim_speed_max',1))])
add(A,'Duplicate the smoke and change its shared surface tint. Both copies change. Make only the mesh and surface material independent, then restore one tint. The texture remains shared because a color edit does not require another copy of its pixels.',[dict(op='duplicate',node='Campfire/Smoke',name='SmokeCopy',properties={'position':{'v3':[2,0,0]}}),at(.5,**surf('Campfire/SmokeCopy','albedo_color',{'color':'b275df'})),at(5,op='unique_surface',node='Campfire/SmokeCopy'),at(5.4,**surf('Campfire/SmokeCopy','albedo_color',{'color':'ffffff'})),at(9,**setp('metadata/disabled',True,'Campfire/SmokeCopy'))])
add(A,'Restore a neutral smoke tint and save the campfire. Keep the individual smoke scene too. The flipbook is an optional appearance layer; the slow rise, growth, and fade still need to work when we return to a single soft texture.',[surf('Campfire/Smoke','albedo_color',{'color':'ffffff'}),at(.5,op='save_branch',node='Campfire',path='res://effects/campfire.tscn'),at(1,op='save_branch',node='Campfire/Smoke',path='res://effects/smoke.tscn'),at(2,**surf('Campfire/Smoke','albedo_texture',{'resource':'res://assets/soft-dot.tres'})),at(2.3,**surf('Campfire/Smoke','particles_anim_h_frames',1)),at(6,op='save')])
A='Build Rain And Contact'
add(A,'Build rain over an area rather than at one point. A box-shaped emission region covers the stage. Long narrow meshes move downward quickly, so the first visible drops already communicate falling rain.',switch('Campfire','Rain',A)+[at(1.5,**layer('Rain','Drops',96,1.1,new('BoxMesh',size={'v3':[.025,.5,.025]},material=new('StandardMaterial3D',shading_mode=0,transparency=1,vertex_color_use_as_albedo=True)),process((8,10),(0,-2,0),2,ramp='magic-fade.tres',direction={'v3':[0,-1,0]},emission_shape=3,emission_box_extents={'v3':[4,.05,3]}),False,position={'v3':[0,5,0]}))])
add(A,'Add a particle collision box at the ground and a separate splash pool. A floor mesh alone does not create particle contact. The splash emitter begins inactive and uses rigid contact to emerge above the surface. It receives individual particle births from the parent effect.',[dict(op='add',node='Rain',class_name='GPUParticlesCollisionBox3D',name='Ground',properties={'position':{'v3':[0,-1,0]},'size':{'v3':[10,2,10]}}),at(.5,**layer('Rain','Splash',64,.35,sphere(.035),process((2.5,3.5),(0,-6,0),60,ramp='flash-fade.tres',collision_mode=1,collision_bounce=.35),False)),at(1,**setp('metadata/sub_emitter_only',True,'Rain/Splash'))])
add(A,'Connect Drops to the Splash child as its sub-emitter. Use contact-driven emission and one splash particle per contact. The visible test must show births at impact positions; a decorative ground emitter would be a different mechanism.',[setp('sub_emitter','../Splash','Rain/Drops'),at(.3,**proc('Rain/Drops','collision_mode',2)),at(.6,**proc('Rain/Drops','sub_emitter_mode',3)),at(.9,**proc('Rain/Drops','sub_emitter_amount_at_collision',1)),at(1.3,**play('Rain'))])
add(A,'Disable the contact mechanism, then restore it. Watch the ground rather than the top of the frame. This comparison separates falling streaks from contact splashes and checks that the child pool is doing the job we claimed.',[proc('Rain/Drops','sub_emitter_mode',0),at(5,**proc('Rain/Drops','sub_emitter_mode',3))])
add(A,'Orbit across the rain volume and inspect its visibility bounds. The emitter must cover the playable view, and the bounds must cover the moving particles. A large box does not repair missing coverage or create a collision surface.',[view(45,True),at(4,**setp('visibility_aabb',{'aabb':[-5,-7,-4,10,9,8]},'Rain/Drops')),at(8,**view(45,False))])
add(A,'Keep the splash capacity explicit: sixty-four slots and a short lifetime. Stop new rain, wait for the existing drops and splashes to finish, then replay. Save the effect with the renderer and contact-test evidence that actually passed.',[setp('preview_loop',False,'Rain'),at(.3,op='call',node='Rain',method='stop'),at(4,**play('Rain')),at(9,op='save_branch',node='Rain',path='res://effects/rain.tscn'),at(9.5,op='save')])
A='Build Dust And Trails'
add(A,'Move to the two-dimensional ground test. Add a one-shot dust emitter at the contact line. Upward launch and downward gravity make a short puff that returns toward the ground instead of floating like smoke.',[dict(op='open',path='res://arena2d.tscn'),at(.5,op='select',node='FrameGuide'),at(.9,op='zoom',node='FrameGuide'),at(1.3,op='add',class_name='GPUParticles2D',name='Dust',properties={'position':{'v2':[0,100]},'amount':24,'lifetime':.65,'one_shot':True,'explosiveness':1,'texture':{'resource':'res://assets/soft-dot.tres'},'process_material':new('ParticleProcessMaterial',particle_flag_disable_z=True,direction={'v3':[0,-1,0]},initial_velocity_min=70,initial_velocity_max=140,gravity={'v3':[0,180,0]},spread=70,scale_min=.1,scale_max=.25,color={'color':'bd9e78'})})])
add(A,'Reduce the spread, then restore a wider ground puff. Keep the contact line fixed while comparing the silhouettes. The effect should tell us where the contact happened; moving the emitter to hide a weak shape would change the question.',[proc('Dust','spread',20),at(4,**proc('Dust','spread',70)),at(4.4,op='call',node='Dust',method='restart')])
add(A,'Duplicate the emitter as a trail and make its process resource unique. Turn one-shot off and spread births through time. Its lower speed and shorter lifetime make a persistent movement cue rather than another impact.',[dict(op='duplicate',node='Dust',name='Trail'),at(.4,op='unique',node='Trail',property='process_material'),at(.8,**setp('one_shot',False,'Trail')),at(1.1,**setp('explosiveness',0,'Trail')),at(1.4,**setp('lifetime',.5,'Trail')),at(1.7,**proc('Trail','initial_velocity_min',15)),at(2,**proc('Trail','initial_velocity_max',30))])
add(A,'Move the emitter with local coordinates off. The trail records positions left behind the source. Turn local coordinates on for comparison, then restore world space. That single choice changes a trail into an attached cloud.',[setp('moving',True),at(.3,**setp('local_coords',False,'Trail')),at(4,**setp('local_coords',True,'Trail')),at(8,**setp('local_coords',False,'Trail'))])
add(A,'Turn the trail condition off and let existing dust finish. Turn it on again while the source moves. A continuous effect has both an on-state and an off-state; the off-state is part of the design, not cleanup to consider later.',[setp('repeat_preview',False),at(.3,**setp('stream_enabled',False)),at(5,**setp('stream_enabled',True))])
add(A,'Save separate dust and trail scenes with their independent process resources. Their texture can remain shared. The ground puff communicates a contact event, while the trail communicates movement over time.',[dict(op='save_branch',node='Dust',path='res://effects/dust_2d.tscn'),at(.4,op='save_branch',node='Trail',path='res://effects/trail_2d.tscn'),at(.8,op='save')])
A='Coordinate Magic And Timing'
add(A,'Return to the three-dimensional stage and build a magic effect. Its controller will coordinate a charge, a release, and an aftermath. Timing makes the action readable before we increase detail or particle count.',[dict(op='open',path='res://arena.tscn'),at(.5,**view()),*[{**x,'at':1+i*.35} for i,x in enumerate(switch('Rain','Magic',A))]])
add(A,'Add a compact blue charge cloud that emits for one and a half seconds. Its small volume announces preparation. The controller owns that time window, so the particle scene does not have to decide when a gameplay action is allowed.',[layer('Magic','Charge',32,1,mesh(.18,blend=1),process((.05,.2),spread=180,ramp='magic-fade.tres',emission_shape=1,emission_sphere_radius=.35),False,**{'metadata/emit_until':1.5})])
add(A,'Add a fast release burst with a delayed start, followed by a slower ring. These are familiar layers with different timing and color. The release begins after the charge; adding everything at time zero would erase that distinction.',[layer('Magic','Release',28,.9,sphere(.05),process((2,4),spread=180,ramp='magic-fade.tres'),**{'metadata/delay':1.5}),at(.5,**layer('Magic','Ring',1,.8,mesh(1,'ring.tres',1),process((0,0),spread=0,ramp='magic-fade.tres',scale_min=4,scale_max=4,scale_curve={'resource':'res://assets/grow.tres'}),**{'metadata/delay':1.6}))])
add(A,'Add a brief light pulse at release, then compare with the light disabled. The pulse affects nearby surfaces; the bright particle material affects the image. Keep both only if their combined timing helps the action read.',[dict(op='add',node='Magic',class_name='OmniLight3D',name='Pulse',properties={'position':{'v3':[0,1,0]},'light_color':{'color':'469cff'},'omni_range':4,'light_energy':0}),at(.5,**play('Magic')),at(5,**setp('visible',False,'Magic/Pulse')),at(5.3,**play('Magic')),at(10,**setp('visible',True,'Magic/Pulse'))])
add(A,'Open the actual controller. It tracks elapsed time, starts each layer at its delay, and stops continuous births at their stated end. It also computes when the last particle can finish before freeing a spawned instance.',[dict(op='script',path='res://effect.gd',line=26)])
add(A,'Replay the complete charge and release from a second angle. The sequence should remain readable at game scale without relying on the editor selection outline. Save it as a reusable scene with the timing controls intact.',[view(100,False),at(.5,**play('Magic')),at(7,op='save_branch',node='Magic',path='res://effects/magic.tscn'),at(8,op='save')])
A='Package And Price'
add(A,'The library now has explosion, smoke, campfire, rain, dust, trail, and magic resources. Each scene has a visual job and explicit replay or emission behavior. Reuse the scene contract; do not copy unexplained parameter piles into the game.',[setp('heading',A),at(.4,**view()),at(.8,op='select',node='Magic')])
add(A,'Open the spawn path in the stage script. Space loads a saved scene, marks it for bounded disposal, and calls play. The scene’s tree-exited signal updates the cleanup count, so repeated use has observable state.',[dict(op='script',path='res://stage.gd',line=23)])
add(A,'Run the stage and trigger the saved explosion three times. Watch the active-instance counter rise and return to zero after the smoke tail finishes. This checks the whole layered scene, not only the first bright frame.',[setp('visible',False,'Magic'),at(.3,**setp('selected_effect','Explosion')),at(.6,op='save'),at(1,op='play_custom',path='res://arena.tscn'),at(2,op='game_input',key='Space',pressed=True),at(2.2,op='game_input',key='Space',pressed=False),at(5.5,op='game_input',key='Space',pressed=True),at(5.7,op='game_input',key='Space',pressed=False),at(9,op='game_input',key='Space',pressed=True),at(9.2,op='game_input',key='Space',pressed=False)])
add(A,'Compare the same stage with layers off and on using the recorded measurement fixture. Its report names the renderer, resolution, warm-up, sample count, and instrument. A smooth recording alone tells us none of those costs.',[dict(op='stop'),at(.5,op='script',path='res://tests/price.gd',line=1)])
add(A,'Read the actual cost report beside those conditions. Zero or unavailable GPU timing is not free rendering. Look for the difference from the empty stage, and preserve both the useful shape and a budget for the rest of the frame.',[dict(op='play_custom',path='res://price_report.tscn')])
add(A,'Return to the saved library and its source. Keep the procedural texture generator, tests, renderer notes, and complete-effect recordings with the scenes. A reusable effect is something the next person can trigger, inspect, change, and finish safely.',[dict(op='stop'),at(.5,**setp('visible',True,'Explosion')),at(.9,**setp('visible',False,'Magic')),at(1.3,**view(45,True)),at(8,**view(45,False)),at(9,op='save')])
d=dict(slug='claude-liam-lecture-a-practical-godot-vfx-library',title='A Practical Godot VFX Library',payoff='Build reusable effects with clear visual jobs',summary='Assemble, compare, and test layered effects in real Godot scenes.',framing='Can a library of particle presets tell us why an effect works? We will build the layers, expose their timing, and test what survives reuse.',question='A VFX library is\na folder of presets',trigger='folder of presets',replacement='set of tested contracts',terms=[dict(term='Layer',meaning='One visual job within a larger effect'),dict(term='Alpha',meaning='A value controlling transparency'),dict(term='Overdraw',meaning='Repeated drawing over the same pixels'),dict(term='Sub-emitter',meaning='An emitter receiving births from particles')],body=b,recap=['An effect reads through onset, peak, and decay.','Smoke, flame, and sparks have different visual jobs.','Contact splashes need a verified birth mechanism.','A trail needs a coordinate space and an off-state.','A controller coordinates timing and complete cleanup.','A reusable library includes evidence and measured limits.'],prompt='Choose one effect and make two variants for different game situations using its existing layers. Explain each changed setting and test the result at gameplay scale.',checks=['Check: the variants communicate different intentions.','Check: repeated playback remains bounded and clean.'],coverage='Six acts: layered explosion with five soloable jobs and tail fault; alpha/additive smoke/fire and a procedural four-cell flipbook; unwanted shared surface edits and independent surface repair retaining texture identity; contact-driven rain/sub-emitter with capacity/cleanup; ground dust and world-space trails in 2D; delayed charge/release and optional light; reusable scenes, repeated lifecycle checks, and actual renderer pricing. Native visual verification is still required before accepting any effect-specific claim.',facts='All planned nodes, enum values, resource properties, contact behavior, complete disposal, and performance numbers must be tested on installed Godot 4.7.2. No performance result is supplied by this authoring file. Rain claims are provisional until native evidence confirms collision-driven splash births. If unsupported, preserve the failed test and use the plan’s explicitly labeled fallback; never describe decorative births as collisions.',sources='Original procedural stage, textures, controllers and effect recipes. https://docs.godotengine.org/en/stable/tutorials/3d/particles/subemitters.html\nhttps://docs.godotengine.org/en/stable/classes/class_particleprocessmaterial.html\nhttps://docs.godotengine.org/en/stable/classes/class_basematerial3d.html\nSupplied course particle chapter and SERIES-PLAN.md.')
if __name__=='__main__':Path('film4.json').write_text(json.dumps(d,indent=2));author(d)
